  "不使用时，建议在 Shizuku 里停止服务，并关闭开发者选项中的无线调试。": "쓰지 않을 때는 Shizuku에서 서비스를 중지하고 개발자 옵션의 무선 디버깅을 끄는 것이 좋습니다.",
  "如果你没有开启过后台操作，却发现它是开着的，请立即关闭，并在 Shizuku 里撤销本应用的授权。": "백그라운드 작업을 켠 적이 없는데 켜져 있다면 즉시 끄고 Shizuku에서 이 앱의 권한을 취소하세요.",
  "开启后台操作前请确认：\n\n· 对话里的手机任务会在一块你看不到的屏幕上进行。\n· 需要 Shizuku 给本应用授予更高的系统权限；只在你自己的手机上开启，只给你信任的应用授权。\n· 需要审批的操作照样先问你；付款、转账一律不做；你设为禁止的应用，AI 不会读取或操作。\n· 可以随时在「设备与工具」里查看后台屏幕、移到前台或关闭。\n· 不使用时，建议在 Shizuku 里停止服务，并关闭无线调试。\n\n确定开启吗？": "백그라운드 작업을 켜기 전에 확인하세요:\n\n· 대화에서 시작한 휴대폰 작업이 보이지 않는 화면에서 진행됩니다.\n· Shizuku가 이 앱에 더 높은 시스템 권한을 부여합니다. 본인 휴대폰에서만 켜고, 믿을 수 있는 앱에만 허용하세요.\n· 승인이 필요한 작업은 여전히 먼저 묻고, 결제와 송금은 절대 하지 않으며, 금지로 설정한 앱은 AI가 읽거나 조작하지 않습니다.\n· ‘기기 및 도구’에서 언제든 백그라운드 화면을 보고, 앞으로 가져오거나, 끌 수 있습니다.\n· 쓰지 않을 때는 Shizuku에서 서비스를 중지하고 무선 디버깅을 끄는 것이 좋습니다.\n\n켤까요?",
