  "推荐 Documents/AgentWorkspace 下的独立项目文件夹，便于用手机文件管理器查找、编辑和分享。此建议仅填写新建表单。": "Documents/AgentWorkspace 아래에 별도의 프로젝트 폴더를 두면 휴대폰 파일 관리자에서 찾고, 편집하고, 공유하기 쉽습니다. 이 추천은 새로 만들기 양식만 채웁니다.",
