  "推荐先下载 Qwen3.5 0.8B Q4。本机推理支持文字与工具调用；Qwen3.5 图片理解需配套视觉组件。模型按需下载，校验完成后才能使用。": "먼저 Qwen3.5 0.8B Q4를 다운로드하는 것을 권장합니다. 기기 내 추론은 텍스트와 도구 호출을 지원하며, Qwen3.5 이미지 이해에는 전용 비전 구성 요소가 필요합니다. 모델은 필요할 때 다운로드하며 검증이 끝난 뒤에 쓸 수 있습니다.",
