  "官方技能": "공식 스킬",
  "AI 按你的要求保存的技能，只在这台手机上": "요청에 따라 AI가 저장한 스킬, 이 휴대폰에만 있음",
  "删除技能": "스킬 삭제",
  "已装 {0}（随应用预装），有新版本时会在这里更新": "{0} 설치됨(앱에 기본 포함). 새 버전이 나오면 여기에서 업데이트됩니다",
  "删除技能「{0}」？": "스킬 ‘{0}’을(를) 삭제할까요?",
  "安装官方技能": "공식 스킬 설치",
  "导入其他技能（非官方，未经测试）": "다른 스킬 가져오기(비공식, 테스트 안 됨)",
  "别人仓库或文件里的技能没有经过本项目测试，可能写得不好，也可能引导 AI 做你不想做的事。只导入你信任的来源，安装前先看清每个技能的说明。": "다른 사람의 저장소나 파일에 있는 스킬은 이 프로젝트에서 테스트하지 않았습니다. 잘못 작성되었거나 AI가 원하지 않는 일을 하도록 이끌 수 있습니다. 믿을 수 있는 출처에서만 가져오고, 설치 전에 각 스킬의 설명을 꼼꼼히 확인하세요.",
  "官方技能包还在准备中（github.com/{0} 还没有发布）": "공식 스킬 팩은 준비 중입니다(github.com/{0}에 아직 릴리스가 없습니다)",
