  "最新版本 {0}，共 {1} 个技能，都经过真机测试": "최신 버전 {0}: 스킬 {1}개, 모두 실제 휴대폰에서 테스트됨",
  "最新版本 {0}": "최신 버전 {0}",
  "读取官方技能失败：{0}": "공식 스킬을 불러오지 못했습니다: {0}",
