  "非官方 · 未经测试": "비공식 · 테스트 안 됨",
  "非官方技能，没有经过本项目测试。请确认来源可信、每个技能的用途都符合预期再安装。": "비공식 스킬이며 이 프로젝트에서 테스트하지 않았습니다. 출처를 믿을 수 있고 각 스킬의 용도가 예상과 같은지 확인한 뒤 설치하세요.",
  "正在下载官方技能…": "공식 스킬 다운로드 중…",
  "官方技能 {0} 已安装": "공식 스킬 {0} 설치됨",
  "检查技能更新": "스킬 업데이트 확인",
  "技能是写给 AI 的做事说明（比如「每天签到」怎么一步步做）。AI 只看到每个技能的名字和用途，遇到对应的请求时才读取全文。技能本身不能执行任何操作，AI 的每一步仍按你的确认规则执行。": "스킬은 AI에게 주는 작업 설명서입니다(예: ‘매일 출석 체크’를 단계별로 어떻게 하는지). AI는 각 스킬의 이름과 용도만 보고, 해당하는 요청이 있을 때 전체 내용을 읽습니다. 스킬 자체는 아무 작업도 할 수 없으며, AI의 모든 단계는 여전히 확인 규칙을 따릅니다.",
  "从 GitHub 导入": "GitHub에서 가져오기",
  "owner/repo 或 github.com 链接": "owner/repo 또는 github.com 링크",
