  "本机模型在 {0} 上运行（GPU 加速为测试功能；遇到问题可改用「仅 CPU」并反馈）。": "기기 내 모델이 {0}에서 실행 중입니다(GPU 가속은 테스트 기능입니다. 문제가 있으면 ‘CPU만’으로 바꾸고 알려 주세요).",
  "已选仅 CPU；这台手机的 {0} 也能运行本机模型。": "CPU만 선택되어 있습니다. 이 휴대폰의 {0}에서도 기기 내 모델을 실행할 수 있습니다.",
  "正在检查 {0} 能否运行本机模型（第一次约需一两分钟），完成前使用 CPU。": "{0}에서 기기 내 모델을 실행할 수 있는지 확인하는 중입니다(처음에는 1~2분 정도). 끝날 때까지 CPU를 사용합니다.",
  "已选仅 CPU。选择「自动」后会先检查 {0} 能否运行本机模型。": "CPU만 선택되어 있습니다. ‘자동’을 고르면 먼저 {0}에서 기기 내 모델을 실행할 수 있는지 확인합니다.",
  "将检查 {0} 能否运行本机模型，完成前使用 CPU。": "{0}에서 기기 내 모델을 실행할 수 있는지 확인합니다. 끝날 때까지 CPU를 사용합니다.",
  "本机模型运行中，结束后显示 GPU 信息。": "기기 내 모델이 실행 중입니다. 끝나면 GPU 정보를 표시합니다.",
  "这台手机的 {0} 驱动较旧，不能运行本机模型，使用 CPU。GPU 加速支持 Adreno 7xx/8xx（如骁龙 8 Gen 1 及更新）。": "이 휴대폰의 {0} 드라이버가 오래되어 기기 내 모델을 실행할 수 없으므로 CPU를 사용합니다. GPU 가속은 Adreno 7xx/8xx(스냅드래곤 8 Gen 1 이후 등)를 지원합니다.",
  "这台手机的 GPU 暂不支持（GPU 加速支持高通骁龙 Adreno 7xx/8xx），使用 CPU。": "이 휴대폰의 GPU는 아직 지원되지 않습니다(GPU 가속은 퀄컴 스냅드래곤 Adreno 7xx/8xx 지원). CPU를 사용합니다.",
