  "液态玻璃让顶栏、输入区和菜单变成会折射光线的玻璃，内容从下方经过时会在边缘弯曲。在较旧的手机上更耗电。": "리퀴드 글래스는 상단 바, 입력창, 메뉴를 빛을 굴절시키는 유리로 바꿉니다. 아래로 지나가는 내용은 가장자리에서 휘어 보입니다. 오래된 휴대폰에서는 전력을 더 씁니다.",
