  "诊断日志": "진단 로그",
  "引擎出错、卡住或连不上时，把日志发给开发者排查。访问令牌和 API 密钥会自动隐藏；日志里可能有任务内容片段，请只发给信任的人。": "엔진에 오류가 나거나, 멈추거나, 연결되지 않을 때 이 로그를 개발자에게 보내 원인을 찾을 수 있습니다. 액세스 토큰과 API 키는 자동으로 가려집니다. 로그에 작업 내용 일부가 들어 있을 수 있으니 믿을 수 있는 사람에게만 보내세요.",
