  "操作失败：{0}": "실패: {0}",
  "已恢复，正在重启引擎以完成恢复...": "복원했습니다. 마무리를 위해 엔진을 다시 시작하는 중...",
  "恢复会用备份替换这台手机上的会话、记忆、工作区文件和设置（当前数据会保留一份），然后重启引擎。API 密钥不在备份里，恢复后需要重新填写。继续？": "복원하면 이 휴대폰의 대화, 기억, 워크스페이스 파일, 설정이 백업 내용으로 바뀌고(현재 데이터는 한 부 보존됩니다) 엔진이 다시 시작됩니다. API 키는 백업에 들어 있지 않으므로 복원 후 다시 입력하세요. 계속할까요?",
  "换手机或重装前保存会话和设置": "휴대폰 교체나 재설치 전에 대화와 설정 보관",
  "备份包含全部会话、记忆、定时任务与流程、内置工作区的文件，以及模型和界面设置。不包含 API 密钥、已下载的本机模型和开发工具链；放在手机公共文件夹里的工作区本来就在你的文件中，也不会重复打包。": "백업에는 모든 대화, 기억, 예약 작업과 흐름, 내장 워크스페이스의 파일, 모델 및 화면 설정이 들어갑니다. API 키, 다운로드한 기기 내 모델, 개발 도구 모음은 들어가지 않습니다. 휴대폰 공용 폴더의 워크스페이스는 이미 내 파일에 있으므로 중복해서 넣지 않습니다.",
  "创建备份": "백업 만들기",
  "保存为一个 zip 文件，位置由你选择": "zip 파일 하나로 원하는 위치에 저장합니다",
