  "用备份替换这台手机上的数据，引擎会重启": "이 휴대폰의 데이터를 백업으로 바꾸며 엔진이 다시 시작됩니다",
  "恢复前的数据会在手机里保留一份，直到下次恢复时被替换。恢复后请到模型设置里重新填写 API 密钥。": "복원 전 데이터는 다음 복원 때까지 휴대폰에 한 부 남습니다. 복원 후 모델 설정에서 API 키를 다시 입력하세요.",
  "本机": "기기 내",
