  "切换": "전환",
  "删除模型配置“{0}”？密钥不会被删除。": "모델 프로필 ‘{0}’을(를) 삭제할까요? 키는 삭제되지 않습니다.",
  "还没有保存的配置。设置好服务商和模型后，点下面的按钮保存。": "아직 저장된 프로필이 없습니다. 서비스와 모델을 설정한 뒤 아래 버튼으로 저장하세요.",
