  "正在切换到 {0}，引擎需要重启...": "{0}(으)로 전환하는 중입니다. 엔진을 다시 시작해야 합니다...",
  "给这个配置起个名字": "이 프로필의 이름 정하기",
  "已保存的模型配置": "저장된 모델 프로필",
  "在常用的服务商和模型之间一键切换。云端模型之间切换不用重启引擎；切换到或离开本机模型时会重启。API 密钥按服务商地址保存在系统密钥库，配置里不含密钥。": "자주 쓰는 서비스와 모델을 한 번에 전환합니다. 클라우드 모델끼리 바꿀 때는 엔진을 다시 시작하지 않고, 기기 내 모델로 바꾸거나 기기 내 모델에서 바꿀 때는 다시 시작합니다. API 키는 서비스 주소별로 시스템 키 저장소에 보관되며, 프로필에는 키가 들어가지 않습니다.",
  "把当前设置存为配置": "현재 설정을 프로필로 저장",
