  "请重新回答。": "다시 답해 주세요.",
  "正在编辑之前的消息：发送后会替换它和之后的对话（已改动的文件不会撤销）": "이전 메시지를 편집하는 중: 보내면 이 메시지와 이후 대화가 바뀝니다(이미 바뀐 파일은 되돌리지 않습니다)",
  "通知触发": "알림 트리거",
  "收到特定通知时自动处理": "특정 알림을 받으면 자동으로 처리",
  "收到指定应用的通知时，让 AI 按你写的要求处理，比如“快递短信来了就记下取件码”。只读取你选定应用的通知，其他通知不会被读取；通知内容只交给这次触发的任务，不会另外保存。": "지정한 앱에서 알림이 오면 AI가 적어 둔 요청대로 처리합니다(예: ‘택배 문자가 오면 수령 코드를 기록해 줘’). 고른 앱의 알림만 읽고 다른 알림은 읽지 않습니다. 알림 내용은 이번에 실행된 작업에만 전달되며 따로 저장되지 않습니다.",
  "根据通知自动处理": "알림에 따라 자동 처리",
  "通知使用权": "알림 접근 권한",
  "添加规则": "규칙 추가",
  "关键词（可选，用逗号分隔，包含其中任意一个才触发）": "키워드(선택, 쉼표로 구분하며 하나라도 포함되면 실행)",
  "要做什么": "할 일",
  "例如：把通知里的取件码和快递柜位置追加到工作区的 快递.md": "예: 알림 속 수령 코드와 택배함 위치를 워크스페이스의 택배.md에 추가",
  "每次运行前先问我": "실행할 때마다 먼저 묻기",
  "任务在当前会话里运行，使用当前的模型。执行权限和平时一样，需要批准的操作仍会先问你。每条规则至少间隔 30 秒，每天最多运行 30 次。": "작업은 현재 대화에서 현재 모델로 실행됩니다. 실행 권한은 평소와 같으며, 승인이 필요한 작업은 여전히 먼저 묻습니다. 규칙마다 최소 30초 간격으로, 하루 최대 30회 실행됩니다.",
  "最近触发": "최근 트리거",
