  "还没有规则": "아직 규칙이 없습니다",
  "在下面选一个应用，写下收到它的通知时要做什么。": "아래에서 앱을 고르고, 그 앱의 알림이 오면 할 일을 적으세요.",
  "还没有触发记录": "아직 트리거 기록이 없습니다",
