  "规则已添加；打开上面的开关后才会生效": "규칙을 추가했습니다. 위의 스위치를 켜야 적용됩니다",
  "内置浏览器": "내장 브라우저",
  "AI 用它打开网页、点按钮、填表和截图。打开网页和点击需要你批准，只读取当前页面不用。它的登录状态与应用界面分开保存。": "AI는 이것으로 웹 페이지를 열고, 버튼을 누르고, 양식을 채우고, 스크린샷을 찍습니다. 페이지 열기와 클릭에는 승인이 필요하지만 현재 페이지를 읽기만 할 때는 필요 없습니다. 로그인 상태는 앱 화면과 따로 저장됩니다.",
  "测试浏览器": "브라우저 테스트",
  "清除浏览数据": "인터넷 사용 기록 삭제",
  "正在打开 example.com...": "example.com 여는 중...",
  "网页已打开（{0}），但截图是空白的：这台手机不能给后台网页截图，AI 会改用读取文字": "페이지는 열렸지만({0}) 스크린샷이 비어 있습니다. 이 휴대폰은 백그라운드 페이지를 캡처할 수 없어 AI가 대신 텍스트를 읽습니다",
  "浏览器正常：已打开“{0}”，截图 {1}×{2}": "브라우저 정상: ‘{0}’을(를) 열었고 스크린샷은 {1}×{2}입니다",
  "清除内置浏览器的登录状态、Cookie 和网站数据？": "내장 브라우저의 로그인 상태, 쿠키, 사이트 데이터를 삭제할까요?",
  "已清除浏览数据": "인터넷 사용 기록을 삭제했습니다",
  "浏览器": "브라우저",
  "查看网页": "페이지 보기",
  "全局入口": "어디서나 실행",
  "悬浮球、快捷设置开关、桌面图标快捷方式": "플로팅 버튼, 빠른 설정 타일, 아이콘 바로가기",
  "在手机的任何地方都能快速开一个新对话。": "휴대폰 어디서나 바로 새 대화를 시작할 수 있습니다.",
  "悬浮球": "플로팅 버튼",
  "在其他应用上方显示一个小圆球：点一下展开操作手机、新对话、语音提问、圈选提问（圈出屏幕上想问的部分）和录音速记；拖动可以移到屏幕两侧，拖到底部的 × 上就隐藏它。需要允许“显示在其他应用上层”。「操作手机」在当前应用上弹出小窗，直接告诉 AI 要做什么，它用无障碍服务替你点按、输入和滑动；系统设置等页面会隐藏悬浮球，可以先在别处呼出小窗，再让 AI 打开设置去做。圈选提问每次会请你允许截取屏幕；在“设备与工具”里开启无障碍服务后就不再询问。": "다른 앱 위에 작은 동그란 버튼을 표시합니다. 누르면 휴대폰 조작, 새 대화, 음성으로 질문, 동그라미로 질문(화면에서 궁금한 부분을 동그라미로 그려 질문), 음성 메모를 열 수 있습니다. 끌어서 화면 양옆으로 옮길 수 있고, 아래쪽 ×로 끌면 숨겨집니다. ‘다른 앱 위에 표시’ 권한이 필요합니다. ‘휴대폰 조작’은 지금 앱 위에 작은 창을 띄우며, AI에게 할 일을 말하면 접근성 서비스로 대신 누르고, 입력하고, 밉니다. 시스템 설정 같은 화면에서는 버튼이 숨겨지므로 다른 곳에서 창을 연 뒤 AI에게 설정을 열어 처리하도록 하세요. 동그라미로 질문은 매번 화면 캡처 허용을 요청하지만, ‘기기 및 도구’에서 접근성 서비스를 켜면 더 이상 묻지 않습니다.",
  "添加到快捷设置": "빠른 설정에 추가",
  "添加“快捷提问”小组件": "‘빠른 질문’ 위젯 추가",
  "像搜索框一样随时提问，也能语音或拍照": "검색창처럼 언제든 질문, 음성이나 사진도 가능",
  "添加“任务动态”小组件": "‘작업 현황’ 위젯 추가",
  "正在执行和等待批准的任务": "실행 중이거나 승인 대기 중인 작업",
  "添加“常用任务”小组件": "‘자주 쓰는 작업’ 위젯 추가",
  "一键开始你的常用任务": "자주 쓰는 작업을 한 번에 시작",
  "也可以长按桌面空白处，在“小组件”里找到 Agent Workspace。": "홈 화면의 빈 곳을 길게 눌러 ‘위젯’에서 Agent Workspace를 찾을 수도 있습니다.",
  "请在弹出的窗口里确认添加": "열린 창에서 추가를 확인하세요",
  "无法自动添加，请长按桌面空白处，从“小组件”里添加": "자동으로 추가할 수 없습니다. 홈 화면의 빈 곳을 길게 눌러 ‘위젯’에서 추가하세요",
  "下拉通知栏就能点“问 Agent”": "알림창을 내리면 ‘Agent에게 묻기’를 누를 수 있습니다",
  "也可以下拉通知栏，进入快捷开关的编辑页面，把“问 Agent”拖进去。": "알림창을 내려 빠른 설정 편집 화면에서 ‘Agent에게 묻기’를 끌어다 넣을 수도 있습니다.",
  "长按桌面上的 Agent Workspace 图标，可以直接选“新对话”“语音提问”或“拍照提问”。": "홈 화면의 Agent Workspace 아이콘을 길게 누르면 ‘새 대화’, ‘음성으로 질문’, ‘사진으로 질문’을 바로 고를 수 있습니다.",
  "请在打开的列表里找到 Agent Workspace，允许它“显示在其他应用上层”，返回后悬浮球就会出现": "열린 목록에서 Agent Workspace를 찾아 ‘다른 앱 위에 표시’를 허용하세요. 돌아오면 플로팅 버튼이 나타납니다",
  "已添加到快捷设置": "빠른 설정에 추가했습니다",
  "没有获得“显示在其他应用上层”权限，悬浮球未开启": "‘다른 앱 위에 표시’ 권한이 없어 플로팅 버튼이 꺼져 있습니다",
  "快捷设置里已经有“问 Agent”了": "‘Agent에게 묻기’가 이미 빠른 설정에 있습니다",
  "无法自动添加，请从快捷开关的编辑页面手动拖入": "자동으로 추가할 수 없습니다. 빠른 설정 편집 화면에서 직접 끌어다 넣으세요",
  "截图已添加到这次对话，输入你的问题吧": "스크린샷을 이 대화에 첨부했습니다. 질문을 입력하세요",
  "后台服务": "백그라운드 서비스",
  "AI 启动的、一直运行的程序": "AI가 시작해 계속 실행 중인 프로그램",
  "AI 可以启动需要一直运行的程序，比如本地网页服务或机器人。任务结束后它们继续运行，直到你在这里停止，或者引擎停止。勾选“随引擎启动”的服务会在引擎重启后自动重新运行。": "AI는 로컬 웹 서버나 봇처럼 계속 실행되어야 하는 프로그램을 시작할 수 있습니다. 작업이 끝나도 여기에서 중지하거나 엔진이 멈출 때까지 계속 실행됩니다. ‘엔진과 함께 시작’에 체크한 서비스는 엔진이 다시 시작된 뒤 자동으로 다시 실행됩니다.",
  "息屏后继续运行": "화면이 꺼져도 계속 실행",
  "有服务运行时让手机在息屏后不休眠，更耗电。不开启时，息屏一段时间后服务会暂停，亮屏后继续。": "서비스가 실행되는 동안 화면이 꺼져도 휴대폰이 절전 모드로 들어가지 않아 배터리를 더 씁니다. 끄면 화면이 꺼지고 얼마 뒤 서비스가 일시 중지되고, 화면이 켜지면 다시 실행됩니다.",
