  "记忆已满（{0} 条），请先删除不需要的": "기억이 가득 찼습니다({0}개). 필요 없는 것을 먼저 삭제하세요",
  "记忆里不能保存密码、密钥、验证码或证件、卡号": "기억에는 비밀번호, 키, 인증 코드, 신분증이나 카드 번호를 저장할 수 없습니다",
  "每条记忆最多 {0} 字，请只写一件事": "기억 하나는 최대 {0}자입니다. 한 가지 내용만 적어 주세요",
  "添加一条记忆": "기억 추가",
  "最多 {0} 条，每条不超过 {1} 字，按主题分类。对话时只带上最新的记忆（约 {2} 字以内），更早的由 AI 按需搜索；AI 每次任务最多自动记 {3} 条，相似的内容不会重复记，密码、验证码、证件和卡号一律不记。": "최대 {0}개, 하나당 {1}자 이내이며 주제별로 분류됩니다. 대화에는 최신 기억(약 {2}자 이내)만 포함하고, 그보다 오래된 것은 AI가 필요할 때 검색합니다. AI가 한 작업에서 스스로 기록하는 것은 최대 {3}개이며, 비슷한 내용은 중복해서 기록하지 않고 비밀번호, 인증 코드, 신분증, 카드 번호는 절대 기록하지 않습니다.",
