  "5 分钟": "5분",
  "对话、记忆和 API 设置都存在这台手机上。开启后，重新打开应用或从后台回来时需要解锁；悬浮球、圈选提问这些快捷入口不受影响。": "대화, 기억, API 설정은 모두 이 휴대폰에 저장됩니다. 켜면 앱을 다시 열거나 백그라운드에서 돌아올 때 잠금을 해제해야 합니다. 플로팅 버튼, 동그라미로 질문 같은 바로가기는 영향을 받지 않습니다.",
  "这台手机没有设置锁屏密码（或系统低于 Android 9），无法使用应用锁。": "이 휴대폰에 화면 잠금이 설정되어 있지 않아(또는 Android 9 미만) 앱 잠금을 쓸 수 없습니다.",
  "其他应用发起任务": "다른 앱에서 시작한 작업",
  "允许 Tasker、快捷指令等应用直接发起任务": "Tasker, 단축어 같은 앱이 작업을 바로 시작하도록 허용",
  "关闭时，每次有应用发起任务都会先弹窗让你确认，并显示来源和内容。发起的任务和平时一样，需要确认的操作仍会询问。": "꺼져 있으면 앱이 작업을 시작할 때마다 출처와 내용을 보여 주고 먼저 확인을 받습니다. 시작된 작업은 평소와 같으며, 확인이 필요한 작업은 여전히 묻습니다.",
  "用法：发送 Intent，动作": "사용법: Intent를 보냅니다. 액션",
  "，目标 Activity": ", 대상 Activity",
  "，附加文本": ", 추가 텍스트",
  "（要做的事）；要操作手机再加布尔值": "(할 일). 휴대폰을 조작하려면 불리언 값",
  "= true。": "= true를 추가합니다.",
  "联系人、位置与系统开关": "연락처, 위치, 시스템 스위치",
  "允许后，AI 可以按名字查联系人的电话、查看手机当前位置。短信只会在短信应用里替你写好，由你自己点发送。音量、亮度、勿扰和媒体播放可以让 AI 调整（需要你确认）；Wi‑Fi 和蓝牙只能由你在弹出的面板里开关。": "허용하면 AI가 이름으로 연락처의 전화번호를 찾고 휴대폰의 현재 위치를 확인할 수 있습니다. 문자는 메시지 앱에서 대신 작성만 하고, 보내기는 직접 누릅니다. 음량, 밝기, 방해 금지, 미디어 재생은 AI가 조정할 수 있습니다(확인 필요). Wi‑Fi와 블루투스는 열리는 패널에서 직접 켜고 끕니다.",
  "联系人": "연락처",
  "位置": "위치",
  "已允许：AI 可以按名字查电话": "허용됨: AI가 이름으로 전화번호를 찾을 수 있습니다",
  "已允许：AI 可以查看手机位置": "허용됨: AI가 휴대폰 위치를 확인할 수 있습니다",
  "自动触发": "자동 트리거",
  "在这些时候自动执行一段指令或一个可复用流程，结果发到当前对话。同一个触发在冷却时间内只运行一次。": "이런 때에 지시나 재사용 흐름을 자동으로 실행하고 결과를 현재 대화로 보냅니다. 같은 트리거는 대기 시간 안에 한 번만 실행됩니다.",
  "什么时候": "언제",
  "开始充电时": "충전을 시작할 때",
  "连上 Wi‑Fi 时": "Wi‑Fi에 연결될 때",
  "打开某个应用时": "특정 앱을 열 때",
  "Wi‑Fi 名称（留空表示任意网络）": "Wi‑Fi 이름(비워 두면 모든 네트워크)",
  "做什么": "할 일",
  "执行下面的指令": "아래 지시 실행",
  "例如：汇总一下今天的通知": "예: 오늘 받은 알림 요약해 줘",
  "需要操作手机": "휴대폰 조작 필요",
