  "添加自动触发": "자동 트리거 추가",
  "应用（输入名字可以搜索）": "앱(이름을 입력해 검색)",
  "运行流程「{0}」": "흐름 ‘{0}’ 실행",
  "冷却 {0} 分钟": "대기 {0}분",
  "删除这个自动触发？": "이 자동 트리거를 삭제할까요?",
  "还没有自动触发": "아직 자동 트리거가 없습니다",
  "已添加：结果会发到当前对话": "추가됨: 결과는 현재 대화로 보내집니다",
  "网关与备用 Key": "게이트웨이 및 예비 키",
  "走网关或代理需要额外请求头时填在这里；同一服务商有多个 Key 时，一个被限流或失效会自动换下一个。都按当前服务商地址加密保存在手机里，保存后不再显示内容，重启引擎后生效。": "게이트웨이나 프록시를 거칠 때 추가 요청 헤더가 필요하면 여기에 입력합니다. 같은 서비스에 키가 여러 개 있으면 하나가 제한되거나 무효가 될 때 자동으로 다음 키로 바꿉니다. 둘 다 현재 서비스 주소별로 암호화되어 휴대폰에 저장되며, 저장 후에는 내용을 다시 표시하지 않습니다. 엔진을 다시 시작한 뒤 적용됩니다.",
  "自定义请求头（每行一个，例如 X-Team: abc）": "사용자 지정 요청 헤더(한 줄에 하나, 예: X-Team: abc)",
  "备用 API Key（每行一个）": "예비 API 키(한 줄에 하나)",
  "保存（会替换之前的设置）": "저장(이전 설정을 대체합니다)",
  "请求头：{0}": "요청 헤더: {0}",
  "备用 Key {0} 个": "예비 키 {0}개",
  "已设置 · {0}": "설정됨 · {0}",
  "还没有设置": "설정 안 됨",
  "请求头要写成「名称: 值」：{0}": "요청 헤더는 ‘이름: 값’ 형식으로 적어 주세요: {0}",
  "已保存，重启引擎后生效": "저장했습니다. 엔진을 다시 시작한 뒤 적용됩니다",
  "朗读": "소리 내어 읽기",
  "朗读失败：{0}": "읽어 주지 못했습니다: {0}",
  "这里没有语音输入": "여기에서는 음성 입력을 쓸 수 없습니다",
  "连续语音对话：说完会自动发送，回复读完后继续听。取消语音输入即可结束。": "연속 음성 대화: 말을 마치면 자동으로 보내고, 답변을 다 읽은 뒤 다시 듣습니다. 음성 입력을 취소하면 끝납니다.",
  "已结束连续语音对话": "연속 음성 대화를 끝냈습니다",
  "连续语音对话": "연속 음성 대화",
  "快捷操作 · 不用 AI 直接做": "바로가기 · AI 없이 바로 실행",
  "正在运行{0}…": "{0} 실행 중…",
  "最近任务": "최근 앱",
  "通知栏": "알림창",
  "向上": "위로",
