  "已存为小工具「{0}」，按系统提示放到桌面": "도구 ‘{0}’(으)로 저장했습니다. 시스템 안내에 따라 홈 화면에 놓으세요",
  "长辈模式": "어르신 모드",
  "大按钮、说话提问、回答读出来": "큰 버튼, 말로 질문, 답을 소리 내어 읽기",
