  "点「打给家人」时拨这个号码": "‘가족에게 전화’를 누르면 이 번호로 겁니다",
  "电话只存在这台手机上，不会发给 AI。称呼会告诉 AI，遇到像是骗局的事时，它会提醒先问家人。": "전화번호는 이 휴대폰에만 저장되며 AI에게 보내지 않습니다. 호칭은 AI에게 알려 주어, 사기처럼 보이는 일이 있으면 먼저 가족에게 물어보라고 알려 줍니다.",
