  "设了以后，退出长辈模式要输入这个数字密码，免得误操作退出。可以不设。": "설정하면 어르신 모드에서 나갈 때 이 숫자 비밀번호를 입력해야 하므로 실수로 나가는 일을 막을 수 있습니다. 설정하지 않아도 됩니다.",
