  "还没有测过：在「本机模型」里运行设备测试后再生成": "아직 테스트하지 않았습니다: ‘기기 내 모델’에서 기기 테스트를 실행한 뒤 만드세요",
  "已复制：在 Issues 页面新建一个问题，粘贴进去就行。": "복사했습니다: Issues 페이지에서 새 이슈를 만들고 붙여 넣으세요.",
  "需要你批准：{0}": "승인 필요: {0}",
