  "退出长辈模式？": "어르신 모드에서 나갈까요?",
  "这里核对不了签名：请在手机上的 App 里导入": "여기에서는 서명을 확인할 수 없습니다. 휴대폰의 앱에서 가져오세요",
  "签名对不上：分享码在签名后被改动过": "서명이 맞지 않습니다: 공유 코드가 서명 뒤에 변경되었습니다",
  "没有签名：看不出是谁做的，也不能确认没被改过": "서명 없음: 누가 만들었는지 알 수 없고 변경되지 않았는지도 확인할 수 없습니다",
  "签名：你自己的": "서명: 본인",
  "签名：指纹 {0}，你导入过这个人的{1}": "서명: 지문 {0}, 이 사람의 {1}을(를) 가져온 적이 있습니다",
  "签名：指纹 {0}，第一次见到。可以请对方在「可复用流程」页看自己的指纹，核对一致再装": "서명: 지문 {0}, 처음 보는 상대입니다. 상대방에게 ‘재사용 흐름’ 페이지에서 자신의 지문을 확인해 달라고 하고, 일치하면 설치하세요",
  "控制手机（无障碍服务）：按记下的步骤点击、输入和滑动": "휴대폰 조작(접근성 서비스): 기록한 단계대로 누르기, 입력, 밀기",
  "打开应用：{0}": "앱 열기: {0}",
