  "打开系统设置：{0}": "시스템 설정 열기: {0}",
  "打开网页：{0}": "웹 페이지 열기: {0}",
  "填好号码打开拨号界面：{0}": "번호를 넣고 전화 걸기 화면 열기: {0}",
  "输入文字：{0}": "글자 입력: {0}",
  "会打开安全相关的设置页，只在清楚它要做什么时安装": "보안 관련 설정 페이지를 엽니다. 무엇을 하는지 알 때만 설치하세요",
  "有付款类按钮（{0}）：运行到这一步会被拦下，要你自己点": "결제 버튼이 있습니다({0}): 실행이 이 단계에 오면 멈추고 직접 눌러야 합니다",
  "快捷操作{0}，共 {1} 步": "바로가기 {0}, 총 {1}단계",
  "需要的权限和会做的事：": "필요한 권한과 하는 일:",
  "步骤：": "단계:",
  "……还有 {0} 步": "…외 {0}단계",
  "你的分享指纹：{0}。别人导入你分享的快捷操作时会看到它，可以当面或打电话核对。": "내 공유 지문: {0}. 내가 공유한 바로가기를 가져오는 사람에게 이 지문이 보이므로 직접 만나거나 전화로 확인할 수 있습니다.",
  "电量低于某个值时": "배터리가 일정 수준 아래로 내려갈 때",
  "连上耳机或蓝牙音频设备时": "이어폰이나 블루투스 오디오 기기가 연결될 때",
  "解锁手机时": "휴대폰 잠금을 해제할 때",
  "日程开始前": "일정 시작 전",
  "设备名称（留空表示任意耳机或音箱）": "기기 이름(비워 두면 모든 이어폰이나 스피커)",
  "电量（%）": "배터리(%)",
  "提前几分钟": "몇 분 전",
  "电量低于 {0}% 时": "배터리가 {0}% 아래로 내려갈 때",
  "日程开始前 {0} 分钟": "일정 시작 {0}분 전",
  "每个日程一次": "일정마다 한 번",
  "日程触发要读取日历：允许后再点一次添加": "일정 트리거는 캘린더를 읽습니다. 허용한 뒤 ‘추가’를 다시 누르세요",
  "预计约 {0}，多则 {1}": "약 {0}, 많으면 {1} 예상",
  "（还没有用量记录，按常见情况估算）": "(아직 사용량 기록이 없어 일반적인 값으로 추정)",
  "备份口令（可选）": "백업 암호(선택)",
  "不填就不加密": "비워 두면 암호화하지 않습니다",
  "备份口令": "백업 암호",
  "再输入一次": "한 번 더 입력",
  "再输入一次备份口令": "백업 암호를 한 번 더 입력",
  "设了口令，备份会加密成 .awbackup 文件，别人拿到也打不开；恢复时要输入同一个口令。口令不会保存在任何地方，忘了就无法恢复。": "암호를 설정하면 백업이 .awbackup 파일로 암호화되어 다른 사람이 손에 넣어도 열 수 없습니다. 복원할 때는 같은 암호를 입력해야 합니다. 암호는 어디에도 저장되지 않으므로 잊어버리면 복원할 수 없습니다.",
  "保存为一个文件，位置由你选择": "파일 하나로 원하는 위치에 저장합니다",
  "口令不对，或者备份文件已损坏。请再输入一次备份口令：": "암호가 틀렸거나 백업 파일이 손상되었습니다. 백업 암호를 다시 입력하세요:",
  "这个备份已加密，请输入备份口令：": "이 백업은 암호화되어 있습니다. 백업 암호를 입력하세요:",
  "两次输入的口令不一样": "두 번 입력한 암호가 다릅니다",
  "这个版本不能加密备份": "이 버전에서는 백업을 암호화할 수 없습니다",
  "新装应用有风险时提醒我": "새로 설치한 앱이 위험해 보이면 알리기",
  "大约每 30 分钟看一次：新装的应用拿到大权限，或已有的应用新拿到设备管理器、无障碍这类权限时，发一条通知，点开就是这一页。": "약 30분마다 확인합니다. 새로 설치한 앱이 큰 권한을 가졌거나, 기존 앱이 기기 관리자나 접근성 같은 권한을 새로 얻으면 알림을 보내며, 누르면 이 페이지가 열립니다.",
  "求救": "도움 요청",
  "设了电话后，长辈界面会有「求救」按钮：按下后写好一条给家人的短信，由长辈自己按发送。": "전화번호를 설정하면 어르신 화면에 ‘도움 요청’ 버튼이 생깁니다. 누르면 가족에게 보낼 문자를 작성하고, 보내기는 어르신이 직접 누릅니다.",
  "求救短信带上位置": "도움 요청 문자에 위치 포함",
  "已允许": "허용됨",
  "正在写求救短信…": "도움 요청 문자를 쓰고 있어요…",
  "求救短信写好了，带上了你的位置。按发送键发给{0}；发完回来，再按「打给{0}」。": "도움 요청 문자를 다 썼어요. 지금 위치도 넣었어요. 보내기 버튼을 눌러 {0}에게 보내세요. 보낸 뒤 돌아와서 ‘{0}에게 전화’를 누르세요.",
  "求救短信写好了。按发送键发给{0}；发完回来，再按「打给{0}」。": "도움 요청 문자를 다 썼어요. 보내기 버튼을 눌러 {0}에게 보내세요. 보낸 뒤 돌아와서 ‘{0}에게 전화’를 누르세요.",
  "没能写好求救短信：{0}": "도움 요청 문자를 쓰지 못했어요: {0}",
