  "「{0}」的历史版本": "‘{0}’의 이전 버전",
  "这个文件还没有更早的版本。AI 或你改动它之前，会先存一份。": "이 파일에는 아직 이전 버전이 없습니다. AI나 사용자가 바꾸기 전에 한 부를 먼저 저장합니다.",
  "最近没有改动。AI 或你改动、删除文件之前，会先存一份旧内容，保留 30 天。": "최근 변경이 없습니다. AI나 사용자가 파일을 바꾸거나 삭제하기 전에 이전 내용을 한 부 저장해 30일 동안 보관합니다.",
  "读取历史失败：{0}": "기록을 불러오지 못했습니다: {0}",
