  "关闭后不会在后台检查，仍可随时手动检查。从 GitHub 发布页下载，安装前会校验 SHA-256 和签名；安装需要你在系统安装界面确认。": "끄면 백그라운드에서 확인하지 않지만 언제든 직접 확인할 수 있습니다. GitHub 릴리스 페이지에서 다운로드하며, 설치 전에 SHA-256과 서명을 검증합니다. 설치하려면 시스템 설치 화면에서 확인해야 합니다.",
