  "自动：先连 ModelScope 魔搭，连不上再换 Hugging Face。各来源是同一份文件，下载完都按固定的 SHA-256 校验；暂停后换来源会接着下载。": "자동: 먼저 Hugging Face에 연결하고, 연결되지 않으면 ModelScope로 바꿉니다. 모든 출처는 같은 파일이며, 다운로드 후 고정된 SHA-256으로 검증합니다. 일시 중지한 뒤 출처를 바꿔도 이어서 다운로드합니다.",
