  "系统仍可能暂停后台进程。中断的操作需要检查状态后恢复。": "시스템이 여전히 백그라운드 프로세스를 멈출 수 있습니다. 중단된 작업은 상태를 확인한 뒤 재개하세요.",
  "系统操作": "시스템 조작",
  "系统文件浏览器的「Agent Workspace」入口可浏览工作区和附件，按文件名搜索并读取。编辑请使用应用内文件页或公共文件夹。引擎停止后，请打开 Agent 启动引擎再重试。": "시스템 파일 탐색기의 ‘Agent Workspace’ 항목에서 워크스페이스와 첨부 파일을 둘러보고, 파일 이름으로 검색해 읽을 수 있습니다. 편집은 앱의 파일 페이지나 공용 폴더에서 하세요. 엔진이 멈추면 Agent를 열어 엔진을 시작한 뒤 다시 시도하세요.",
  "系统无障碍设置": "시스템 접근성 설정",
  "实时画面": "실시간 화면",
  "AI 操作手机时直接看当前画面：截图更快，画面在动（视频、动画）也能截到，Android 10 及以下也能截图。开启时系统会请你允许录制屏幕，状态栏会显示录屏标志；画面只留在手机上供 AI 截图用，半小时不用会自动关闭。": "AI가 휴대폰을 조작할 때 현재 화면을 바로 봅니다. 스크린샷이 더 빠르고, 움직이는 화면(동영상, 애니메이션)도 찍을 수 있으며, Android 10 이하에서도 찍을 수 있습니다. 켜면 시스템이 화면 녹화 허용을 요청하고 상태 표시줄에 녹화 표시가 나타납니다. 화면은 휴대폰에만 남아 AI 스크린샷에만 쓰이며, 30분 동안 쓰지 않으면 자동으로 꺼집니다.",
