  "在电脑版 Agent Workspace 打开「设置 → 手机连接」，打开「允许手机连接这台电脑」，再点「显示配对二维码」。然后拍下二维码，或在下面填电脑的地址和配对码。": "컴퓨터용 Agent Workspace에서 「설정 → 휴대폰 연결」을 열고 「휴대폰이 이 컴퓨터에 연결하도록 허용」을 켠 뒤 「페어링 QR 코드 표시」를 누르세요. 그 QR 코드를 촬영하거나 아래에 컴퓨터 주소와 페어링 코드를 입력하세요.",
