  "自动": "자동",
  "自动值按可用于模型的内存（含系统可立即回收的部分）、模型上限和已测速度推荐。手动上下文保留所选容量，内存估算作为建议；实际分配失败会明确提示。扩展模式可使用系统剩余交换内存。": "자동 값은 모델에 쓸 수 있는 메모리(시스템이 바로 회수할 수 있는 부분 포함), 모델 한도, 측정된 속도를 바탕으로 권장됩니다. 수동 컨텍스트는 선택한 용량을 유지하고 메모리 추정은 참고로만 보여 줍니다. 실제 할당에 실패하면 분명히 알려 줍니다. 확장 모드는 시스템에 남은 스왑을 쓸 수 있습니다.",
