  "电脑上的版本还不接受交到这类对话的任务，请先更新电脑上的 Agent Workspace": "컴퓨터의 버전은 이런 대화에 맡기는 작업을 아직 받지 않습니다. 먼저 컴퓨터의 Agent Workspace를 업데이트하세요",
