  "电脑会直接执行": "컴퓨터가 묻지 않고 실행합니다",
  "电脑上这个对话设为「{0}」：交过去的任务里，运行命令、修改和删除文件、联网等操作都会直接在电脑上执行，不会再询问任何人。拿到这台手机配对令牌的人也能这样做。\n确定要交给它吗？": "이 대화는 컴퓨터에서 「{0}」(으)로 설정되어 있습니다. 맡긴 작업에서 명령 실행, 파일 수정과 삭제, 인터넷 연결 등의 조작이 누구에게도 묻지 않고 컴퓨터에서 실행됩니다. 이 휴대폰의 페어링 토큰을 얻은 사람도 똑같이 할 수 있습니다.\n이 작업을 맡길까요?",
  "我了解风险，交给电脑": "위험을 이해하고 맡기기",
