  "{0} 交来的任务会直接在这台手机上开始，不再先问你。每一步仍按手机的审批规则：需要审批的操作会停下来等你，银行卡号、身份证号、验证码仍会拦下。": "{0}이(가) 맡긴 작업은 먼저 묻지 않고 이 휴대폰에서 시작됩니다. 각 단계는 여전히 휴대폰의 승인 규칙을 따릅니다. 승인이 필요한 조작은 멈춰서 기다리고, 은행 카드 번호, 신분증 번호, 인증 코드는 여전히 차단됩니다.",
  "自动接受": "자동으로 수락",
  "电脑交来的任务每次都会先问你": "컴퓨터가 맡긴 작업은 매번 먼저 묻습니다",
  "电脑交来的任务会自动开始": "컴퓨터가 맡긴 작업이 자동으로 시작됩니다",
  "不再接受电脑交来的任务": "컴퓨터가 맡긴 작업을 더 이상 받지 않습니다",
  "有些文件没能读取：{0}": "일부 파일을 읽지 못했습니다: {0}",
  "先选要发送的文件": "먼저 보낼 파일을 선택하세요",
  "来自手机": "휴대폰에서",
  "正在发送 {0} 个文件...": "파일 {0}개 보내는 중...",
  "已发送 {0} 个文件，电脑开始处理": "파일 {0}개를 보냈습니다. 컴퓨터가 처리를 시작했습니다",
  "已发送 {0} 个文件到电脑：{1}": "파일 {0}개를 컴퓨터로 보냈습니다: {1}",
  "剪贴板里没有文字": "클립보드에 텍스트가 없습니다",
  "先写要发送的文字": "먼저 보낼 텍스트를 입력하세요",
  "已发到 {0}": "{0}(으)로 보냈습니다",
  "两边各选一个知识库": "양쪽에서 지식 베이스를 하나씩 선택하세요",
  "已对应，点「现在同步」开始": "연결했습니다. 「지금 동기화」를 누르면 시작합니다",
  "正在同步知识库...": "지식 베이스 동기화 중...",
  "同步完成：复制到手机 {0} 篇，复制到电脑 {1} 篇": "동기화 완료: 휴대폰으로 {0}개, 컴퓨터로 {1}개 복사",
  "正在查找…": "찾는 중…",
  "没有找到": "찾지 못했습니다",
  "确认电脑上打开了「允许手机连接这台电脑」，并且手机和电脑在同一个网络": "컴퓨터에서 「휴대폰이 이 컴퓨터에 연결하도록 허용」이 켜져 있고 휴대폰과 컴퓨터가 같은 네트워크에 있는지 확인하세요",
  "正在等待配对": "페어링 대기 중",
  "证书指纹 {0}": "인증서 지문 {0}",
  "填入": "채우기",
  "核对电脑屏幕上配对码旁的证书指纹是否为 {0}。一致再输入配对码；不一致说明这不是你的电脑，不要配对。": "컴퓨터 화면의 페어링 코드 옆에 있는 인증서 지문이 {0}인지 확인하세요. 같으면 페어링 코드를 입력하고, 다르면 내 컴퓨터가 아니니 페어링하지 마세요.",
  "先选一台电脑": "먼저 컴퓨터를 선택하세요",
  "正在发到电脑...": "컴퓨터로 보내는 중...",
  "已在电脑上新建对话「{0}」{1}": "컴퓨터에서 새 대화 「{0}」을(를) 시작했습니다{1}",
  "，结果会出现在「待发送与接力」": ". 결과는 「보낼 항목 및 이어받기」에 표시됩니다",
  "在电脑上继续": "컴퓨터에서 이어서 하기",
  "把这段对话的文字和图片发到电脑，在电脑上新建一个对话接着做。": "이 대화의 텍스트와 사진을 컴퓨터로 보내 컴퓨터에서 새 대화로 이어서 합니다.",
  "让电脑接着做什么（可选）": "컴퓨터가 이어서 할 일(선택)",
  "附近的电脑": "주변 컴퓨터",
  "列出同一网络里打开了「允许手机连接这台电脑」的电脑。点一台会填好地址，再输入电脑上显示的配对码。": "같은 네트워크에서 「휴대폰이 이 컴퓨터에 연결하도록 허용」을 켠 컴퓨터를 보여 줍니다. 하나를 누르면 주소가 채워지니, 컴퓨터에 표시된 페어링 코드를 입력하세요.",
  "查找附近的电脑": "주변 컴퓨터 찾기",
  "等你审批": "승인 대기",
  "电脑上的任务要做这些操作，在这里允许或拒绝，和在电脑上点一样。每次只放行这一个操作。": "컴퓨터의 작업이 이런 조작을 하려고 합니다. 여기서 허용하거나 거부하면 컴퓨터에서 누른 것과 같습니다. 그 조작 하나만 허용됩니다.",
  "电脑交来的任务": "컴퓨터가 맡긴 작업",
  "电脑想在这台手机上做事时": "컴퓨터가 이 휴대폰에서 작업하려고 할 때",
  "不接受": "받지 않음",
  "由手机自己的 AI 执行，手机的保护规则照常生效：银行卡号、身份证号、验证码、卸载应用等仍会拦下，删除文件和发消息仍逐条询问。": "휴대폰 자체의 AI가 실행하며 휴대폰의 보호 규칙은 그대로 적용됩니다. 은행 카드 번호, 신분증 번호, 인증 코드, 앱 제거 등은 차단되고, 파일 삭제와 메시지 보내기는 매번 묻습니다.",
  "交任务给电脑": "컴퓨터에 작업 맡기기",
  "电脑上的对话": "컴퓨터의 대화",
  "正在运行": "실행 중",
  "收件箱": "받은 편지함",
  "电脑上任务的结果、定时任务的结果，以及电脑发到这台手机的文件、文字和对话。收到的文件放在工作区的「来自电脑」文件夹。": "컴퓨터의 작업과 예약 작업의 결과, 컴퓨터가 이 휴대폰으로 보낸 파일, 텍스트, 대화입니다. 받은 파일은 작업 공간의 「来自电脑」 폴더에 저장됩니다.",
  "发文件到电脑": "컴퓨터로 파일 보내기",
  "文件放进电脑上打开的文件夹里的「来自手机」。也可以在其他应用里分享到「发到电脑」。": "파일은 컴퓨터에서 연 폴더 안의 「来自手机」에 들어갑니다. 다른 앱에서 「컴퓨터로 보내기」로 공유할 수도 있습니다.",
  "选文件": "파일 선택",
  "选照片": "사진 선택",
  "让电脑处理（可选）": "컴퓨터가 할 일(선택)",
  "同时加入电脑的知识库": "컴퓨터의 지식 베이스에도 추가",
  "发送到电脑": "컴퓨터로 보내기",
  "浏览电脑上的文件": "컴퓨터의 파일 보기",
  "发文字": "텍스트 보내기",
  "粘贴剪贴板": "클립보드 붙여넣기",
  "知识库同步": "지식 베이스 동기화",
  "对应起来的两个知识库互相补齐对方没有的文档，按内容去重，之后每 6 小时自动同步一次。删除文档不会同步。": "연결한 두 지식 베이스는 상대에게 없는 문서를 서로 채우고(내용으로 중복 제거), 이후 6시간마다 자동으로 동기화합니다. 문서 삭제는 동기화되지 않습니다.",
  "电脑的知识库": "컴퓨터의 지식 베이스",
  "手机的知识库": "휴대폰의 지식 베이스",
  "对应起来": "연결하기",
  "现在同步": "지금 동기화",
  "设备": "기기",
