  "交给电脑做": "컴퓨터에 맡기기",
  "让电脑做：{0}": "컴퓨터에 맡기기: {0}",
  "交给 {0} 的 {1} 个任务还没有结果，移除后就收不到了。仍然移除？": "{0}에 맡긴 작업 {1}개의 결과가 아직 오지 않았습니다. 제거하면 받을 수 없습니다. 그래도 제거할까요?",
  "已发送 {0} 个文件，但电脑没有开始处理：{1}": "파일 {0}개를 보냈지만 컴퓨터가 처리를 시작하지 않았습니다: {1}",
  "已发送 {0} 个文件；没发出去的：{1}": "파일 {0}개를 보냈습니다. 보내지 못한 파일: {1}",
  "锁屏时收不到电脑的消息": "잠금 중에는 컴퓨터 알림을 받을 수 없습니다",
  "锁屏后系统会暂停这个应用，这段时间电脑的审批、请求和任务完成通知都要等亮屏后才到。允许后台运行后，锁屏也能收到。": "잠그면 시스템이 이 앱을 일시 중지하므로 컴퓨터의 승인 요청, 요청, 작업 완료 알림은 화면이 켜진 뒤에야 도착합니다. 백그라운드 실행을 허용하면 잠금 중에도 받을 수 있습니다.",
  "锁屏时系统仍会暂停这个应用。还差一步：{0}": "잠금 중에도 시스템이 이 앱을 일시 중지합니다. 한 단계 더: {0}",
  "选择模型": "모델 선택",
  "国内可以直接使用，价格低。": "중국 네트워크에서 바로 쓸 수 있고 요금이 저렴합니다.",
  "通义千问（阿里云百炼）": "Qwen(Alibaba Cloud Model Studio)",
  "国内可以直接使用。": "중국 네트워크에서 바로 쓸 수 있습니다.",
  "智谱 GLM": "Zhipu GLM",
  "需要能访问 OpenAI 的网络。": "OpenAI에 접속할 수 있는 네트워크가 필요합니다.",
  "需要能访问 Anthropic 的网络。": "Anthropic에 접속할 수 있는 네트워크가 필요합니다.",
  "需要能访问 Google 的网络。": "Google에 접속할 수 있는 네트워크가 필요합니다.",
  "还没有选好模型，AI 没法回答。先选一个，你写的消息会留在输入框里。": "아직 모델을 고르지 않아 AI가 답할 수 없습니다. 먼저 하나를 고르세요. 작성한 메시지는 입력란에 남습니다.",
  "先选一个模型，AI 才能回答。以后可以点输入框下面的模型按钮更换。": "AI가 답하려면 먼저 모델을 고르세요. 나중에 입력란 아래의 모델 버튼으로 바꿀 수 있습니다.",
  "先把 API 密钥粘贴到上面的框里": "먼저 위 칸에 API 키를 붙여 넣으세요",
  "无法保存": "저장할 수 없습니다",
  "正在用这个密钥连接 {0}…": "이 키로 {0}에 연결하는 중…",
  "无法连接服务商": "제공자에 연결할 수 없습니다",
  "密钥可用，正在切换到 {0}…": "키를 쓸 수 있습니다. {0}(으)로 전환하는 중…",
  "已设置 {0}，正在重新连接…": "{0}을(를) 설정했습니다. 다시 연결하는 중…",
  "服务商一直没有回应，请稍后再试": "제공자가 응답하지 않습니다. 잠시 후 다시 시도하세요",
  "这个版本没有可下载的本机模型": "이 버전에는 내려받을 수 있는 기기 내 모델이 없습니다",
  "已经下载了 {0}，点下面的按钮就能用。第一次回答前要先准备几分钟，之后就快了。": "{0}은(는) 이미 내려받았습니다. 아래 버튼을 누르면 쓸 수 있습니다. 첫 답변 전에 몇 분간 준비하고, 그 뒤로는 빨라집니다.",
  "使用这个模型": "이 모델 사용",
  "推荐 {0}：下载 {1}，需要约 {2} 可用内存。下载完自动切换；第一次回答前要先准备几分钟，之后就快了。": "추천: {0}. 다운로드 {1}, 사용 가능한 메모리 약 {2}이(가) 필요합니다. 다 받으면 자동으로 전환합니다. 첫 답변 전에 몇 분간 준비하고, 그 뒤로는 빨라집니다.",
  "正在下载…": "내려받는 중…",
  "继续下载并使用": "이어서 내려받고 사용",
  "下载并使用": "내려받고 사용",
  "手机存储空间不够：需要约 {0}，现在还剩 {1}": "저장 공간이 부족합니다: 약 {0}이(가) 필요하고 남은 공간은 {1}입니다",
  "{0} 正在下载，完成或暂停后再试": "{0}을(를) 내려받는 중입니다. 끝나거나 일시 중지한 뒤 다시 시도하세요",
  "网络断了，恢复后自动继续下载": "네트워크가 끊겼습니다. 복구되면 자동으로 이어서 내려받습니다",
  "下载 {0}%，下完会自动切换。可以先关掉这页。": "{0}% 내려받았습니다. 다 받으면 자동으로 전환합니다. 이 페이지는 닫아도 됩니다.",
  "本机模型已就绪，正在切换，引擎需要重启…": "기기 내 모델이 준비됐습니다. 전환을 위해 엔진을 다시 시작하는 중…",
  "本机模型下载失败：{0}": "기기 내 모델을 내려받지 못했습니다: {0}",
  "可以开始了。": "이제 시작할 수 있습니다.",
  "本机模型正在做第一次准备（只需一次，约几分钟，手机会发热）。准备好之前发的消息会排队。": "기기 내 모델이 처음 준비하는 중입니다(한 번만, 몇 분 정도, 휴대폰이 뜨거워집니다). 그동안 보낸 메시지는 대기합니다.",
  "这个版本的应用不能修改这一项": "이 버전의 앱에서는 이 항목을 바꿀 수 없습니다",
  "AI 建议打开这一页：": "AI가 이 페이지를 권합니다:",
  "打开设置页": "설정 페이지 열기",
  "改成 YOLO 后，AI 改文件、运行命令时大多不再先问你。": "YOLO로 바꾸면 AI가 파일을 바꾸거나 명령을 실행하기 전에 대부분 묻지 않습니다.",
  "改成完全访问后，AI 几乎不再询问就能执行操作。": "전체 접근으로 바꾸면 AI가 거의 묻지 않고 작업을 실행합니다.",
  "不用了": "괜찮아요",
  "任务结束后再点「应用更改」：这一项要重启引擎。": "작업이 끝난 뒤 '적용'을 누르세요: 이 항목은 엔진을 다시 시작합니다.",
  "已应用": "적용됨",
  "服务商没有接受 API 密钥：可能没填、填错了或已经失效。": "제공자가 API 키를 받아들이지 않았습니다: 비어 있거나, 잘못 입력했거나, 더 이상 유효하지 않을 수 있습니다.",
  "设置模型": "모델 설정",
  "服务商账户的余额或额度用完了，充值后再试。": "제공자 계정의 잔액이나 한도가 다 떨어졌습니다. 충전한 뒤 다시 시도하세요.",
  "服务商那里没有这个模型名称，换一个模型再试。": "제공자에 이 이름의 모델이 없습니다. 다른 모델을 고르세요.",
  "换模型": "모델 변경",
  "请求太频繁，或这段时间的额度用完了，稍等一会儿再试。": "요청이 너무 많거나 지금 쓸 수 있는 한도를 다 썼습니다. 잠시 뒤 다시 시도하세요.",
  "手机现在没有网络。": "휴대폰이 지금 네트워크에 연결되어 있지 않습니다.",
  "连不上 {0}。请检查网络；国内网络访问不了的服务商，可以换成 DeepSeek 这类国内服务商。": "{0}에 연결할 수 없습니다. 네트워크를 확인하세요. 지금 네트워크에서 닿지 않는 제공자라면 닿는 제공자(중국에서는 DeepSeek 등)로 바꾸세요.",
