  "触感反馈": "햅틱 피드백",
  "仅工作区": "작업 공간만",
  "语音输入用离线识别": "음성 입력에 오프라인 인식 사용",
  "自动检查更新": "업데이트 자동 확인",
  "AI 建议把「{0}」从「{1}」改成「{2}」。点「应用更改」才会生效。": "AI가 '{0}'을(를) '{1}'에서 '{2}'(으)로 바꾸자고 제안합니다. '적용'을 눌러야 바뀝니다.",
  "AI 建议把「{0}」改成「{1}」。点「应用更改」才会生效。": "AI가 '{0}'을(를) '{1}'(으)로 바꾸자고 제안합니다. '적용'을 눌러야 바뀝니다.",
  "AI 建议打开「{0}」这一页。": "AI가 '{0}' 페이지를 열자고 제안합니다.",
  "应用更改": "적용",
  "本应用设置": "이 앱의 설정",
