  "请求来源无效": "요청 출처가 올바르지 않습니다",
  "内容过大": "내용이 너무 큽니다",
  "请求格式无效": "요청 형식이 올바르지 않습니다",
  "会话不存在": "대화가 없습니다",
  "工作区不存在": "워크스페이스가 없습니다",
  "工作区或会话不存在": "워크스페이스 또는 대화가 없습니다",
  "工作区列表已变化，请刷新后重试": "워크스페이스 목록이 바뀌었습니다. 새로고침한 뒤 다시 시도하세요",
  "会话信息已变化，请重试": "대화 정보가 바뀌었습니다. 다시 시도하세요",
  "名称必填，最多 200 个字符": "이름은 필수이며 최대 200자입니다",
  "无法重命名会话": "대화 이름을 바꿀 수 없습니다",
